use grameo_codegen::{emit_with_api,ParserApi};
fn opted(s:&str)->Result<grameo::CompiledGrammar,Vec<grameo::Diagnostic>>{grameo::compile_with_options(s,grameo::CompileOptions{optimizations:true,..Default::default()})}
#[test]fn default_ignores_even_invalid_choice_directives(){for directive in ["// @grameo choice_heads missing","// @grameo choice_heads","// @grameo choice_heads primary primary"]{let source=format!("{directive}\nprimary = {{ \"a\" | \"b\" }}");let g=grameo::compile(&source).unwrap();assert!(g.choice_head_rules().is_empty());assert_eq!(emit_with_api(&g,ParserApi::HYBRID_CAPTURES).unwrap(),emit_with_api(&grameo::compile("primary = { \"a\" | \"b\" }").unwrap(),ParserApi::HYBRID_CAPTURES).unwrap());}}
#[test]fn targets_are_explicit_and_generic(){let source="// @grameo choice_heads dispatch\ndispatch = { \"async\" | \"function\" | name }\nname = @{ ASCII_ALPHA+ }";let g=opted(source).unwrap();assert_eq!(g.choice_head_rules(),&[g.rule_id("dispatch").unwrap()]);let code=emit_with_api(&g,ParserApi::HYBRID_CAPTURES).unwrap();assert!(code.contains("ChoiceHeads{"));assert!(code.contains("fn choice_heads_metadata_is_current"));assert!(!code.contains("literal_head"));}
#[test]fn invalid_target_modes_shapes_and_duplicates_are_rejected(){for source in ["// @grameo choice_heads missing\nprimary={\"a\"|\"b\"}","// @grameo choice_heads\nprimary={\"a\"|\"b\"}","// @grameo choice_heads primary primary\nprimary={\"a\"|\"b\"}","// @grameo choice_heads primary\nprimary={\"a\"}","// @grameo choice_heads primary\nprimary=@{\"a\"|\"b\"}","// @grameo choice_heads primary\nprimary=${\"a\"|\"b\"}","// @grameo choice_heads primary\nprimary=!{\"a\"|\"b\"}"]{assert!(opted(source).is_err(),"{source}");}}
#[test]fn pratt_conflict_is_rejected_in_both_annotation_orders(){for directives in ["// @grameo choice_heads expr\n// @grameo pratt expr atom=atom trailing=consume\n// @grameo operator expr op precedence=1 fixity=infix_left", "// @grameo pratt expr atom=atom trailing=consume\n// @grameo operator expr op precedence=1 fixity=infix_left\n// @grameo choice_heads expr"]{let source=format!("{directives}\nexpr={{atom | atom~op~atom}}\natom={{ASCII_DIGIT}}\nop={{\"+\"}}");assert!(opted(&source).is_err(),"{source}");}}
#[test]fn alternative_limit_is_checked(){let choices=(0..65).map(|i|format!("\"k{i}\"")).collect::<Vec<_>>().join("|");assert!(opted(&format!("// @grameo choice_heads root\nroot={{{choices}}}")).is_err());}
